package ngl.relay.core;
public final class GeminiNode extends HttpNode { public static final String DEFAULT_BASE="https://generativelanguage.googleapis.com/v1beta",DEFAULT_MODEL="gemini-2.0-flash"; public GeminiNode(String id,String key,String base,String model){super(id,key,"google-gemini",blank(base)?DEFAULT_BASE:base.trim(),blank(model)?DEFAULT_MODEL:model.trim());} private static boolean blank(String s){return s==null||s.trim().isEmpty();} protected void configureAuth(java.net.HttpURLConnection c){} public String endpoint(){return baseUrl+"/models/"+model+":generateContent?key="+apiKey;} public String label(){return "Gemini ("+model+")";} protected String requestBody(String p){return "{\"contents\":[{\"parts\":[{\"text\":"+esc(p)+"}]}]}";} protected String extractContent(String b)throws NodeException{String x=jsonStringField(b,"text");if(x==null)throw new NodeException("gemini bad response json",200,b);return x;} }
